#librariesfrom sklearn.linear_model import Lassoimport pandas as pdimport numpy as np from sklearn.model_selection import train_test_splitfrom sklearn.model_selection import GridSearchCVfrom tqdm import tqdmimport randomrandom.seed(42)#import counts matrixcounts = pd.read_csv('/Users/ggraham/Desktop/RGC ML/counts.csv')columns = pd.read_csv('/Users/ggraham/Desktop/RGC ML/counts_columns.csv')rows = pd.read_csv('/Users/ggraham/Desktop/RGC ML/counts_rows.csv')#remove index columnscounts = counts.drop(columns=[counts.columns[0]]) columns = columns.drop(columns=[columns.columns[0]]) rows = rows.drop(columns=[columns.columns[0]]) #extract cyp19a1b from matrixcolumn_index = columns[columns['x'] == 'LOC111577263'].index[0]cyp19a1b = counts.iloc[:, column_index]counts = counts.drop(counts.columns[column_index], axis=1)# train test holdout splittotal_samples = len(rows)train_size = int(0.8 * total_samples)test_size = int(0.1 * total_samples)holdout_size = total_samples - train_size - test_sizeall_indices = list(range(len(rows)))random.shuffle(all_indices)train_indicies = all_indices[:train_size]  test_indices = all_indices[train_size:train_size + test_size]holdout_indices = all_indices[train_size + test_size:]counts_train = counts.iloc[train_indicies]counts_test = counts.iloc[test_indices]counts_holdout = counts.iloc[holdout_indices]rows_train = rows.iloc[train_indicies]rows_test = rows.iloc[test_indices]rows_holdout = rows.iloc[holdout_indices]cyp19a1b_train = cyp19a1b.iloc[train_indicies]cyp19a1b_test = cyp19a1b.iloc[test_indices]cyp19a1b_holdout = cyp19a1b.iloc[holdout_indices]#initialilze lasso modelmodel = Lasso()# perform grid search for best alpha and lambdaparam_grid = {			'alpha': [1, 0.1, 0.01, 0.001, 0.0001, 0.00001]} grid_search = GridSearchCV(    estimator=model,    param_grid=param_grid,    cv=100)grid_search.fit(counts_train, cyp19a1b_train.values)    best_alpha = grid_search.best_params_['alpha']    #Real model timemodel_optimal = Lasso(alpha=0.1)fitted_model = model_optimal.fit(counts_train, cyp19a1b_train)coef = pd.DataFrame({    'coef': fitted_model.coef_,  # Remove the extra brackets    'gene': counts_train.columns  # Use column names from counts})## predicts LOC111577260# mediator of DNA damage checkpoint protein 1-like hmmmm